Consider the following C program:
<pre><code>
#include &lt;stdio.h&gt;

int main(){
    int a;
    int arr[5] = {30,50,10};
    int *ptr;
    ptr = &arr[0] + 1;
    a = *ptr;
    (*ptr)++;
    ptr++;
    printf("%d", a + (*ptr) + arr[1]);
    return 0;
}
</code></pre>
The output of the above program is ___________. (Answer in integer)

Consider the following C program:
<pre><code>
#include &lt;stdio.h&gt;

int g(int n) {
    return (n+10);
}

int f(int n) {
    return g(n*2);
}

int main() {
    int sum, n;
    sum=0;
    for (n=1; n<3; n++)
        sum += g(f(n));
    printf ("%d", sum);
    return 0;
}
</code></pre>
The output of the given C program is ________. (Answer in integer)
